ee:message.ee:set-payload:
%dw 2.0
output application/json
var errorBody = error.cause.errorMessage.payload default {}
var papiError = if (errorBody is Object and errorBody.status?) errorBody else null
---
if (papiError != null) 
	papiError
else {
	"status": vars.httpStatus,
	"code": error.errorType.identifier default "CLIENT_ERROR",
	"message": {
		"message": if (errorBody is String and !isEmpty(errorBody)) 
					errorBody 
				   else 
					error.description default "Error en la solicitud al servicio de validación de riesgo"
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "customer-xapi-services",
			"message": "Error en llamada a customer-papi-services: " ++ (error.errorType.identifier default "HTTP_CLIENT_ERROR")
		}
	]
}

%dw 2.0
output application/json
var errorBody = error.cause.errorMessage.payload default {}
var papiError = if (errorBody is Object and errorBody.status?) errorBody else null
---
if (papiError != null) 
	papiError
else {
	"status": vars.httpStatus,
	"code": if (vars.httpStatus == 503) "SERVICE_UNAVAILABLE" 
			else if (vars.httpStatus == 504) "GATEWAY_TIMEOUT"
			else "PAPI_ERROR",
	"message": {
		"message": if (errorBody is String and !isEmpty(errorBody)) 
					errorBody 
				   else if (vars.httpStatus == 503)
					"El servicio de validación de riesgo no está disponible temporalmente. Por favor intente más tarde."
				   else if (vars.httpStatus == 504)
					"Tiempo de espera agotado al conectar con el servicio de validación de riesgo."
				   else 
					"Error en el servicio de validación de riesgo."
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "customer-xapi-services",
			"message": "Error en llamada a customer-papi-services: " ++ (error.errorType.identifier default "HTTP_SERVER_ERROR")
		}
	]
}

%dw 2.0
output application/json
var isTimeout = (error.errorType.identifier default "") contains "TIMEOUT"
---
{
	"status": 503,
	"code": if (isTimeout) "TIMEOUT" else "SERVICE_UNAVAILABLE",
	"message": {
		"message": if (isTimeout) 
					"Tiempo de espera agotado al conectar con el servicio de validación de riesgo. Por favor intente nuevamente."
				   else 
					"No fue posible conectar con el servicio de validación de riesgo. Por favor intente más tarde."
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "customer-xapi-services",
			"message": "Error de conectividad con customer-papi-services: " ++ (error.errorType.identifier default "CONNECTIVITY_ERROR")
		}
	]
}

%dw 2.0
output application/json
var errorBody = error.cause.errorMessage.payload default {}
---
{
	"status": 500,
	"code": "INTERNAL_SERVER_ERROR",
	"message": {
		"message": if (errorBody is String and !isEmpty(errorBody)) 
					errorBody 
				   else 
					"Error inesperado en el servicio de validación de riesgo."
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "customer-xapi-services",
			"message": "Error inesperado en llamada a customer-papi-services: " ++ (error.errorType.identifier default "UNKNOWN_ERROR")
		}
	]
}

%dw 2.0
output application/json
var errorBody = error.cause.errorMessage.payload default {}
var papiError = if ( errorBody is Object and errorBody.status? ) errorBody else null
---
if ( papiError != null ) papiError
else {
	"status": vars.httpStatus,
	"code": error.errorType.identifier default "CLIENT_ERROR",
	"message": {
		"message": if ( errorBody is String and !isEmpty(errorBody) ) errorBody 
				   else 
					error.description default "Error in the request to the customer360 service."
	},
	"messageServer": error.description default "",
	"cause": [{
		"origin": "customer-xapi-services",
		"message": "Error in call to customer-papi-services: " ++ (error.errorType.identifier default "HTTP_CLIENT_ERROR")
	}]
}

%dw 2.0
output application/json
---
{
	"status": 404,
	"code": "NOT_FOUND",
	"message": {
		"message": "There is no information available for this query."
	},
	"messageServer": "",
	"cause": [{
		"origin": "customer-xapi-services",
		"message": ""
	}]
}

%dw 2.0
output application/json
var errorBody = error.cause.errorMessage.payload default {}
---
{
	"status": 500,
	"code": "INTERNAL_SERVER_ERROR",
	"message": {
		"message": if ( errorBody is String and !isEmpty(errorBody) ) errorBody 
				   else 
					"Unexpected error in the customer360 service."
	},
	"messageServer": error.description default "",
	"cause": [{
		"origin": "customer-xapi-services",
		"message": "Unexpected error in customer-papi-services: " ++ (error.errorType.identifier default "UNKNOWN_ERROR")
	}]
}
